-- Function: public.fn_get_portfolio_experience_participations
-- Backup generated on 2026-10-25 20:33:40

CREATE OR REPLACE FUNCTION public.fn_get_portfolio_experience_participations(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, session_date timestamp with time zone, experience_title character varying, notes text, teacher_name character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT p.id,            (s.session_date + COALESCE(s.end_time, s.start_time, '00:00:00'::TIME))::TIMESTAMPTZ AS session_date,            e.title::VARCHAR AS experience_title,            COALESCE(p.participation_notes, s.actual_notes) AS notes,            COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name     FROM experience_participations p     JOIN experience_sessions s ON p.experience_session_id = s.id     JOIN experiences e ON s.experience_id = e.id     LEFT JOIN teachers t ON s.primary_teacher_id = t.id     WHERE s.tenant_id = p_tenant_id AND p.child_id = p_child_id AND p.participation_status = 'Participated'     ORDER BY s.session_date DESC; END; $function$ ;
